        "state.loading": Entry("正在讀取今日紀錄…", "正在读取今日记录…", "Reading today's history…", "今日の履歴を読み込み中…"),
        "state.noSources": Entry("找不到任何 AI 工具的紀錄資料夾", "找不到任何 AI 工具的记录文件夹", "No AI tool history folder found", "AI ツールの履歴フォルダが見つかりません"),
        "style.led": Entry("LED 儀表", "LED 仪表", "LED Gauge", "LED ゲージ"),
        "style.led.desc": Entry("36 顆 LED 隨速度依序點亮，原本的經典樣式。", "36 颗 LED 随速度依次点亮，原来的经典样式。", "36 LEDs light up as the speed climbs. The original look.", "36 個の LED が速度に合わせて点灯する、おなじみのスタイル。"),
        "style.liquid": Entry("能量液球", "能量液球", "Liquid Energy", "リキッドエナジー"),
        "style.liquid.desc": Entry("發光液體隨速度上漲翻騰，到紅線時沸騰。", "发光液体随速度上涨翻腾，到红线时沸腾。", "Glowing liquid rises and churns with speed, and boils at the redline.", "光る液体が速度とともに満ちて波立ち、レッドラインで沸騰します。"),
        "style.minimal": Entry("極簡圓環", "极简圆环", "Minimal Ring", "ミニマルリング"),
        "style.minimal.desc": Entry("只有數字、細圓環和稱號；最安靜，縮小也清楚。", "只有数字、细圆环和称号；最安静，缩小也清楚。", "Just the number, a thin ring and the title. The calmest, and clear even when small.", "数字と細いリング、称号だけ。いちばん静かで、小さくても読みやすい。"),
        "style.needle": Entry("指針轉速錶", "指针转速表", "Needle Tachometer", "針式タコメーター"),
        "style.needle.desc": Entry("賽車轉速錶：指針掃進紅區，全速時頂住限位。", "赛车转速表：指针扫进红区，全速时顶住限位。", "A racing tach: the needle sweeps into the red zone and pins at full speed.", "レーシングタコメーター。針がレッドゾーンへ振れ、全開でストッパーに張り付きます。"),
        "style.reactor": Entry("反應爐", "反应堆", "Reactor", "リアクター"),
        "style.reactor.desc": Entry("反向旋轉的能量環越轉越快，紅線時迸出電弧。", "反向旋转的能量环越转越快，红线时迸出电弧。", "Counter-rotating energy rings spin up and throw arcs at the redline.", "逆回転するエネルギーリングが加速し、レッドラインで放電します。"),
        "task.card.footnote": Entry("權重是尚未校準的初始值；沒有可靠的測試結果，分數不會變高。分數只在這台電腦上計算，不會上報。", "权重是尚未校准的初始值；没有可靠的测试结果，分数不会变高。分数只在这台电脑上计算，不会上报。", "Weights are uncalibrated starting values; without reliable test results the score stays low. Scores are computed on this computer and never reported.", "重みは未較正の初期値です。信頼できるテスト結果がなければスコアは上がりません。スコアはこのコンピューター上で計算され、送信されることはありません。"),
        "task.card.top": Entry("%d 個 agent 中最高", "%d 个 agent 中最高", "Highest of %d agents", "%d 個の agent で最高"),
        "task.check.build": Entry("建置", "构建", "Build", "ビルド"),
        "task.check.check": Entry("檢查", "检查", "Check", "チェック"),
        "task.check.test": Entry("測試", "测试", "Tests", "テスト"),
        "task.dim.complete": Entry("驗證完整性", "验证完整性", "Verification completeness", "検証の網羅性"),
        "task.dim.complete.desc": Entry("最後一次修改後有建置、有測試，針對性修正後重跑全套", "最后一次修改后有构建、有测试，针对性修正后重跑全套", "After the last edit: built, tested, and the full suite re-run after a targeted fix", "最後の編集の後にビルドとテスト、絞った修正の後は全体を再実行"),
        "task.dim.converge": Entry("錯誤收斂", "错误收敛", "Error convergence", "エラーの収束"),
        "task.dim.converge.desc": Entry("同一個檢查重跑時，不同的錯誤越來越少", "同一个检查重跑时，不同的错误越来越少", "Each re-run of a check shows fewer distinct errors", "同じチェックを再実行するたびに異なるエラーが減る"),
        "task.dim.efficiency": Entry("行為效率", "行为效率", "Behavior efficiency", "行動の効率"),
        "task.dim.efficiency.desc": Entry("每次工具呼叫都有新收穫；打轉、重複、來回修改會扣分", "每次工具调用都有新收获；打转、重复、来回修改会扣分", "Each tool call learns something new; loops, repeats and undone edits lower it", "ツール呼び出しごとに新しい発見。堂々巡り・重複・編集の行き来で下がる"),
        "task.dim.recover": Entry("錯誤恢復", "错误恢复", "Error recovery", "エラーからの回復"),
        "task.dim.recover.desc": Entry("出錯 → 修正 → 通過，嘗試次數越少越高", "出错 → 修正 → 通过，尝试次数越少越高", "Error → fix → pass; fewer attempts score higher", "エラー → 修正 → 通過。試行が少ないほど高い"),
        "task.dim.verify": Entry("驗證成功", "验证成功", "Verification success", "検証の成功"),
        "task.dim.verify.desc": Entry("修改通過可靠的檢查：測試、建置或檢查零失敗", "修改通过可靠的检查：测试、构建或检查零失败", "The changes pass reliable checks with no failures", "変更が信頼できるチェックを失敗なしで通過"),
        "task.dims.title": Entry("評分構成", "评分构成", "Score breakdown", "スコアの内訳"),
        "task.predict.cell.calibrated": Entry("依 %d 個任務", "依 %d 个任务", "%d tasks", "%d タスク"),
        "task.predict.cell.prior": Entry("預設值 · %d/%d", "默认值 · %d/%d", "Prior · %d/%d", "初期値・%d/%d"),
